{
 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    frame_color = next(value for value in counts if value != background)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == frame_color]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        if grid[r0][c] == background:
            out[r0][c] = 2
        if grid[r1][c] == background:
            out[r1][c] = 2
    for r in range(r0 + 1, r1):
        if grid[r][c0] == background:
            out[r][c0] = 2
        if grid[r][c1] == background:
            out[r][c1] = 2
    return out
